bl_info = {
    "name": "NVIDIA DSX Twin Data Cleaner",
    "author": "3dflowhub",
    "version": (1, 0, 0),
    "blender": (4, 0, 0),
    "location": "View3D > Sidebar > 3dflowhub",
    "description": "Cleans and prepares imported digital twin meshes for production.",
    "category": "Mesh",
}

import bpy

class OBJECT_OT_dsx_clean(bpy.types.Operator):
    """Clean selected mesh objects for production"""
    bl_idname = "object.dsx_clean"
    bl_label = "Clean DSX Mesh Data"
    bl_options = {'REGISTER', 'UNDO'}

    def execute(self, context):
        selected_objects = [obj for obj in context.selected_objects if obj.type == 'MESH']

        if not selected_objects:
            self.report({'WARNING'}, "No mesh objects selected")
            return {'CANCELLED'}

        for obj in selected_objects:
            # Make active
            context.view_layer.objects.active = obj

            # Apply rotation and scale
            bpy.ops.object.transform_apply(location=False, rotation=True, scale=True)

            # Enter edit mode to clean mesh data
            bpy.ops.object.mode_set(mode='EDIT')
            bpy.ops.mesh.select_all(action='SELECT')

            # Remove duplicate vertices
            bpy.ops.mesh.remove_doubles(threshold=0.0001)

            # Delete loose vertices
            bpy.ops.mesh.delete_loose()

            bpy.ops.object.mode_set(mode='OBJECT')

            # Ensure every mesh has at least one material
            if len(obj.data.materials) == 0:
                mat = bpy.data.materials.new(name="DSX_Default_Mat")
                obj.data.materials.append(mat)

        self.report({'INFO'}, f"Cleaned {len(selected_objects)} objects successfully.")
        return {'FINISHED'}

class VIEW3D_PT_dsx_clean_panel(bpy.types.Panel):
    bl_label = "DSX Twin Data Cleaner"
    bl_idname = "VIEW3D_PT_dsx_clean_panel"
    bl_space_type = 'VIEW_TYPE' if hasattr(bpy.types, 'VIEW_TYPE') else 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = "3dflowhub"

    def draw(self, context):
        layout = self.layout
        layout.operator("object.dsx_clean")

classes = (
    OBJECT_OT_dsx_clean,
    VIEW3D_PT_dsx_clean_panel,
)

def register():
    for cls in classes:
        bpy.utils.register_class(cls)

def unregister():
    for cls in reversed(classes):
        bpy.utils.unregister_class(cls)

if __name__ == "__main__":
    register()
